<script lang="ts">
 import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import {workspace} from '$lib/stores/workspace';import {infraState,infraCommand,infraId} from '$lib/infra/store';
 let show=false,editing='',project='',name='',kind:'Worker command'|'HTTP request'='Worker command',target='',error='',notice='';
 $: if(project&&!$workspace.projects.some(p=>p.id===project))project='';
 function start(id=''){const job=$infraState.jobs.find(x=>x.id===id);editing=id;project=job?.project||$workspace.projects[0]?.id||'';name=job?.name||'';kind=job?.kind||'Worker command';target=job?.target||'';error='';show=true;}
 function submit(){try{if(editing)infraCommand({type:'job-edit',id:editing,name,kind,target});else infraCommand({type:'job-create',id:infraId(),project,name,kind,target});notice='Application job draft saved. No worker or HTTP request was executed.';show=false;error='';}catch(e){error=e instanceof Error?e.message:'Job configuration invalid.';}}
 function act(fn:()=>void){try{fn();error='';notice='Sample operation recorded. No process or HTTP request was started.';}catch(e){error=e instanceof Error?e.message:'Action unavailable.';}}
 function remove(id:string){if(window.confirm('Delete this sample application job?'))act(()=>infraCommand({type:'job-delete',id}));}
</script>
<Heading title="App jobs" subtitle="Per-application background commands and HTTP tasks."><button class="btn primary" disabled={!$workspace.projects.length} on:click={()=>start()}><Icon name="Plus"/> New app job</button></Heading>
<div class="stack"><div class="callout"><strong>No workers run in the browser.</strong><p>Jobs are metadata only, created disabled by default. Production workers will enforce project isolation, network policy, timeouts and authorization.</p></div>
{#if show}<form class="card stack" on:submit|preventDefault={submit}><h3>{editing?'Edit application job':'Create application job'}</h3><div class="grid2"><label class="field">Project<select bind:value={project} required disabled={!!editing}><option value="">Select project</option>{#each $workspace.projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label class="field">Job name<input bind:value={name} required maxlength="300" placeholder="Send daily summary"/></label><label class="field">Job type<select bind:value={kind}><option>Worker command</option><option>HTTP request</option></select></label><label class="field">Command or HTTPS URL<input bind:value={target} required maxlength="500" placeholder={kind==='HTTP request'?'https://example.com/api/health':'npm run worker'}/></label></div><small>Example configuration; no command or network request will run.</small>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><button class="btn secondary" type="button" on:click={()=>show=false}>Cancel</button><button class="btn primary" type="submit">Save job</button></div></form>{/if}
{#if !show&&error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}
<section class="card table-card"><div class="table-head"><h3>Application jobs</h3></div><div class="table-wrap"><table><thead><tr><th>Job</th><th>Project</th><th>Type</th><th>Enabled</th><th>Actions</th></tr></thead><tbody>{#each $infraState.jobs as j (j.id)}<tr><td><strong>{j.name}</strong><small class="mono" style="display:block">{j.target}</small></td><td><a class="link-btn" href={'/projects/'+j.project+'/overview'}>{$workspace.projects.find(p=>p.id===j.project)?.name||'Missing project'}</a></td><td>{j.kind}</td><td><label class="check"><input type="checkbox" checked={j.enabled} on:change={(e)=>act(()=>infraCommand({type:'job-toggle',id:j.id,enabled:e.currentTarget.checked}))}/>{j.enabled?'On (demo)':'Off'}</label></td><td><div class="table-actions"><button class="btn secondary small" on:click={()=>act(()=>infraCommand({type:'job-run',id:j.id}))}>Simulate run</button><button class="btn secondary small" on:click={()=>start(j.id)}>Edit</button><button class="btn danger small" on:click={()=>remove(j.id)}>Delete</button></div></td></tr>{:else}<tr><td colspan="5">No application jobs configured.</td></tr>{/each}</tbody></table></div></section>
{#if $infraState.jobs.some(j=>j.runs.length)}<section class="card"><h3>Recent simulated runs</h3>{#each $infraState.jobs as j}{#each j.runs.slice(0,3) as run}<div class="setting-row"><div><strong>{j.name}</strong><small style="display:block">{run.label}</small></div><small>{new Date(run.at).toLocaleString()}</small></div>{/each}{/each}</section>{/if}</div>
